import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Принцип равновесия личности и коллектива","description":"","frontmatter":{},"headers":[],"relativePath":"ru/26-个体与集体平衡原理.md","filePath":"ru/26-个体与集体平衡原理.md","lastUpdated":1789183869000}'),l={name:"ru/26-个体与集体平衡原理.md"};function o(d,t,n,h,s,_){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="принцип-равновесия-личности-и-коллектива" tabindex="-1">Принцип равновесия личности и коллектива <a class="header-anchor" href="#принцип-равновесия-личности-и-коллектива" aria-label="Permalink to &quot;Принцип равновесия личности и коллектива&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>26</td></tr><tr><td>Модуль</td><td>Механизм якорей и принципы симбиоза</td></tr><tr><td>Ключевые слова</td><td>Личность и коллектив, Принцип равновесия, Права и обязанности, Симбиотическая этика, Динамическая корректировка</td></tr></tbody></table><h2 id="i-фундаментальныи-вопрос-личности-и-коллектива" tabindex="-1">I. Фундаментальный вопрос личности и коллектива <a class="header-anchor" href="#i-фундаментальныи-вопрос-личности-и-коллектива" aria-label="Permalink to &quot;I. Фундаментальный вопрос личности и коллектива&quot;">​</a></h2><p>Как строить отношение личности и коллектива — один из важнейших вопросов любой цивилизации. Эпоха хищничества отвечала: коллектив существует для личности, сильный пожирает слабого; слабые — лишь ступени для сильных. Этот ответ привёл к опустошению и краху цивилизации. Симбиотическая Цивилизация Якоря даёт иной ответ: личность и коллектив взаимно укрепляются и взаимно осуществляются; коллектив — почва, питающая личности, личности — цветы на этой почве. Только одновременное развитие и совершенствование обоих даёт цивилизации вечное процветание.</p><p>Это не сентиментальный идеал, а строгий вывод из законов Вселенной Истока. В Хэн Юаньчжоу закон сохранения энергии гласит: энергия не создаётся и не уничтожается, лишь превращается и переходит. Отношение личности и коллектива следует тому же: личности отдают энергию коллективу, коллектив возвращает её личностям; поток может быть положительной или отрицательной циркуляцией. В положительной — чем больше отдаёшь, тем больше получаешь; в отрицательной — чем больше берёшь, тем меньше имеешь. Задача симбиотической цивилизации — строить и поддерживать положительную циркуляцию.</p><p>Суть принципа — три тезиса:</p><ol><li><strong>Личность — цель, не средство</strong>: каждая жизнь самоценна; коллектив служит росту каждой личности, а не наоборот</li><li><strong>Коллектив — основа, не придаток</strong>: без коллектива личности теряют почву; развитие личности немыслимо без опоры коллектива</li><li><strong>Вклад и отдача пропорциональны</strong>: доступ личности к поддержке коллектива пропорционален её вкладу; гарантированы и «Больше Труда — Больше Награды», и «Путь для Каждого»</li></ol><h2 id="ii-модель-динамического-равновесия" tabindex="-1">II. Модель динамического равновесия <a class="header-anchor" href="#ii-модель-динамического-равновесия" aria-label="Permalink to &quot;II. Модель динамического равновесия&quot;">​</a></h2><p>Отношение личности и коллектива — не статичная пропорция, а динамический баланс. Сеть реализует его системой «три ядра, два кольца»:</p><table tabindex="0"><thead><tr><th>Измерение</th><th>Центральный механизм</th><th>Цель</th><th>Индекс</th></tr></thead><tbody><tr><td>Энергия</td><td>Накопление и возврат пула</td><td>Вклад и отдача каждой жизни сбалансированы</td><td>Вклад / Отдача</td></tr><tr><td>Рост</td><td>Подбор систем и наставничество</td><td>Каждая жизнь растёт своим путём</td><td>Скорость / Соответствие</td></tr><tr><td>Ресурсы</td><td>Подряд, связанный с результатом</td><td>Получение пропорционально вкладу</td><td>Получение / Ценность вклада</td></tr><tr><td>Ответственность</td><td>Поля ответственности</td><td>Каждая жизнь несёт долю общего дела</td><td>Индекс поля</td></tr><tr><td>Решения</td><td>Демократическое обсуждение</td><td>Воля личности и интерес коллектива выражены</td><td>Участие / Представительство</td></tr></tbody></table><h3 id="_2-1-энергетическое-измерение" tabindex="-1">2.1 Энергетическое измерение <a class="header-anchor" href="#_2-1-энергетическое-измерение" aria-label="Permalink to &quot;2.1 Энергетическое измерение&quot;">​</a></h3><p>Базовое измерение. Жизнь вносит энергию в общий пул культивацией и трудом; коллектив возвращает по доле вклада через сеть якорей. Цикл «вклад — отдача» даёт справедливость распределения и общее процветание.</p><p>Принцип пропорциональности: больше вклада — больше отдачи; но отдача не бывает нулевой — временно не способные вносить (старики, дети, больные, инвалиды) получают базовую защитную энергию коллектива. Это гарантия «Пути для Каждого».</p><h3 id="_2-2-измерение-роста" tabindex="-1">2.2 Измерение роста <a class="header-anchor" href="#_2-2-измерение-роста" aria-label="Permalink to &quot;2.2 Измерение роста&quot;">​</a></h3><p>Каждая жизнь находит свой путь. Триста Изначальных Систем Культивации покрывают разные способности; информационное ядро подбирает и ведёт каждую жизнь по подходящему пути.</p><p>Важно «соответствие, не единообразие»: разные скорости и пути роста нормальны и уважаемы. Сеть не требует одинаковой скорости, но гарантирует возможность роста всем.</p><h3 id="_2-3-измерение-ресурсов" tabindex="-1">2.3 Измерение ресурсов <a class="header-anchor" href="#_2-3-измерение-ресурсов" aria-label="Permalink to &quot;2.3 Измерение ресурсов&quot;">​</a></h3><p>Справедливость распределения. Подряд, связанный с результатом, связывает получение с производственным вкладом; больше работаешь — больше получаешь. Система базовой гарантии даёт каждому поле ответственности, не допуская «потери всего неимущими».</p><h3 id="_2-4-измерение-ответственности" tabindex="-1">2.4 Измерение ответственности <a class="header-anchor" href="#_2-4-измерение-ответственности" aria-label="Permalink to &quot;2.4 Измерение ответственности&quot;">​</a></h3><p>Устойчивость коллектива. Каждая жизнь несёт долю общего дела: обслуживание якорей, строительство сети, передача опыта. Поля ответственности делают это измеримым и оцениваемым.</p><h3 id="_2-5-измерение-решении" tabindex="-1">2.5 Измерение решений <a class="header-anchor" href="#_2-5-измерение-решении" aria-label="Permalink to &quot;2.5 Измерение решений&quot;">​</a></h3><p>Выражение воли личности и верность решений коллектива. Крупные решения — через демократическое обсуждение; профессиональные органы дают техническую оценку и контроль рисков, не допуская ошибок от асимметрии информации.</p><h2 id="iii-защита-прав-личности-и-интересов-коллектива" tabindex="-1">III. Защита прав личности и интересов коллектива <a class="header-anchor" href="#iii-защита-прав-личности-и-интересов-коллектива" aria-label="Permalink to &quot;III. Защита прав личности и интересов коллектива&quot;">​</a></h2><p>Равновесие требует и того, и другого. Двойная система гарантий:</p><h3 id="_3-1-защита-прав-личности" tabindex="-1">3.1 Защита прав личности <a class="header-anchor" href="#_3-1-защита-прав-личности" aria-label="Permalink to &quot;3.1 Защита прав личности&quot;">​</a></h3><ol><li><strong>Право на жизнь</strong>: неприкосновенно; коллектив даёт базовые гарантии</li><li><strong>Право на культивацию</strong>: свободный выбор пути; никто не вправе лишать другого возможности</li><li><strong>Право на приватность</strong>: сеть собирает лишь данные эволюции; тайны личности нерушимы</li><li><strong>Право выхода</strong>: в рамках закона можно изменить симбиотические отношения; принудительный симбиоз запрещён</li><li><strong>Право обжалования</strong>: при ущемлении прав — обращение в арбитражные органы</li></ol><h3 id="_3-2-защита-интересов-коллектива" tabindex="-1">3.2 Защита интересов коллектива <a class="header-anchor" href="#_3-2-защита-интересов-коллектива" aria-label="Permalink to &quot;3.2 Защита интересов коллектива&quot;">​</a></h3><ol><li><strong>Безопасность сети</strong>: повреждение сети якорей — тяжкое преступление; коллектив защищает общую инфраструктуру</li><li><strong>Исполнение обязанностей</strong>: каждая жизнь исполняет свою долю; отказ — соответствующее регулирование</li><li><strong>Энергетический порядок</strong>: кражи энергии и недобросовестная конкуренция запрещены; справедливый порядок — через закон</li><li><strong>Ответ на кризис</strong>: при космических кризисах (вторжение планов, аномалии законов) коллектив вправе мобилизовать всех</li></ol><h3 id="_3-3-соотношение-двух-систем" tabindex="-1">3.3 Соотношение двух систем <a class="header-anchor" href="#_3-3-соотношение-двух-систем" aria-label="Permalink to &quot;3.3 Соотношение двух систем&quot;">​</a></h3><p>Они не антагонистичны, а дополняют друг друга. Защита личности — защита основы коллектива; коллектив, попирающий личностей, недолговечен. Защита коллектива — защита среды роста; личности без коллектива уязвимы.</p><p>При конфликте — «приоритет процедуры»: разрешение через закон и демократическое обсуждение, не силой и не авторитетом. В большинстве случаев конфликта нет; он рождается из недопонимания или сбоев институтов и снимается прозрачными механизмами.</p><h2 id="iv-механизм-динамическои-корректировки" tabindex="-1">IV. Механизм динамической корректировки <a class="header-anchor" href="#iv-механизм-динамическои-корректировки" aria-label="Permalink to &quot;IV. Механизм динамической корректировки&quot;">​</a></h2><p>Равновесие — не формула, а живая настройка через цикл обратной связи:</p><ol><li><strong>По этапу развития</strong>: на старте — крен к коллективу (ресурсы на якоря); в зрелости — крен к личности (автономия)</li><li><strong>По кризису</strong>: при космическом кризисе — временный крен к коллективу; после — автоматический возврат</li><li><strong>По регионам</strong>: разные домены и планы — разные условия; пропорция по месту</li><li><strong>По индивидам</strong>: разные этапы и вклад — разный подход; молодые и старые, сильные и слабые — по-разному, но справедливо</li></ol><p>Все корректировки — через прозрачные процедуры, с обоснованием и надзором; не допускается злоупотребление под видом «интересов коллектива».</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Принцип равновесия личности и коллектива — важнейший ценностный принцип Симбиотической Цивилизации Якоря. Он преодолевает крайности «индивидуализма» и «коллективизма», устанавливая динамический баланс взаимного питания и общего процветания. Это не только основа управления, но и ценностная база культивации: через баланс каждая жизнь получает силу роста от коллектива и возвращает ему, образуя большой справедливый и эффективный цикл, ведущий цивилизацию к вечному процветанию.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>03-共生文明宪章 (Хартия симбиотической цивилизации)</li><li>06-多劳多得分配原理 (Принцип распределения «больше труда — больше награды»)</li><li>08-人人有路保障体系 (Система гарантий «путь для каждого»)</li></ul>',39)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
